  * only navigation, and it is derived from what the thread has produced. A
  * workspace view docks beside the thread instead of replacing it, so the
  * composer never leaves the screen.
  */
 function StudioShell() {
   const { closePanel, clearChat, closeSetup } = useStudio();
   const [showChangelog, setShowChangelog] = useState(false);

   function goHome() {
     clearChat();
     closePanel();
     closeSetup();
   }

   function newConversation() {
     clearChat();
     closePanel();
   }

   useEffect(() => {
     function onKeyDown(event: KeyboardEvent) {
       if (event.key === "Escape") {
         closePanel();
       }
     }
     window.addEventListener("keydown", onKeyDown);
     return () => window.removeEventListener("keydown", onKeyDown);
   }, [closePanel]);

   return (
     <div className="studio-app">
       <main className="stage">
         <StudioBar
           onHome={goHome}
           onNew={newConversation}
           onChangelog={() => setShowChangelog(true)}
         />
         <div className="stage__split">
           <div className="stage__thread">
             <WorkbenchRail />
             <ChatStage />
           </div>
           <WorkspacePanel />
         </div>
       </main>
       <ChangelogModal isOpen={showChangelog} onClose={() => setShowChangelog(false)} />
       <Toasts />
     </div>
   );
 }

 export default function App() {
   return (
     <ErrorBoundary>
       <StudioProvider>
-        <OnboardingProvider>
-          <StudioShell />
-          <FirstRunWizard />
-        </OnboardingProvider>
+        <StudioRuntimeProvider>
+          <OnboardingProvider>
+            <StudioShell />
+            <FirstRunWizard />
+          </OnboardingProvider>
+        </StudioRuntimeProvider>
       </StudioProvider>
     </ErrorBoundary>
   );
 }

