-        part.kind === "ui"
-          ? { type: "data", name: "ui", id: part.id, data: { id: part.id, node: part.node } }
-          : { type: "text", text: part.text },
-      );
-    }
-    return message.content ? [{ type: "text", text: message.content }] : [];
