export async function setConversationHead(
  conversationId: string,
  headId: string | null,
): Promise<Conversation> {
  const body = await sendJson<{ conversation: Conversation }>(
    "PATCH",
    `/api/conversations/${encodeURIComponent(conversationId)}`,
