const sendMessage = useCallback(
  async (
    text: string,
    attachments: ChatAttachmentPayload[] = [],
    options: { from?: string } = {},
  ) => {
    const trimmed = text.trim();
    if ((!trimmed && !attachments.length) || streaming) {
