         raise _TurnFailure(
             StudioError(
                 code=StudioErrorCode.MCP_UNREACHABLE,
                 message=f"MCP server unreachable at {request.mcp_url}",
                 suggestion="Check that the MCP server is running, then try again.",
                 retryable=True,
