+    <Frame>
+      <FailurePanel error={baseError} />
+    </Frame>,
+  );
+
+  await expect.element(screen.getByRole("alert")).toBeVisible();
+  await expect
+    .element(screen.getByRole("alert"))
+    .toHaveTextContent("The Living Studio sidecar is not answering.");
