   }

   .lens__head {
     padding: 14px 16px;
   }

   .lens__body {
     padding: 18px 16px 32px;
   }

   .rail {
     padding-inline: 18px;
   }

   .setup__meta {
     width: calc(100% - 36px);
   }

   .setup__replies {
     margin-left: 0;
   }

   .offline {
