 }

 .doc__toc-item a:hover {
   color: var(--text);
 }

 .doc__toc-item--3 {
   padding-left: 14px;
 }

 .doc__pager {
   display: flex;
   flex-wrap: wrap;
   justify-content: space-between;
   gap: 12px;
   margin-top: 56px;
   padding-top: 28px;
   border-top: 1px solid var(--line);
 }

 .doc__pager-link {
   display: flex;
   flex-direction: column;
   gap: 4px;
   padding: 14px 20px;
   border: 1px solid var(--line);
   border-radius: var(--r-md);
